const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const app = $('#app');
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHTML;
const currency = value => new Intl.NumberFormat('en-AE', {style:'currency', currency:'AED', maximumFractionDigits:0}).format(value || 0);
const number = value => new Intl.NumberFormat('en-AE').format(value);
const initials = name => e((name || 'Unassigned').split(' ').map(n => n[0]).slice(0, 2).join(''));
const dateKey = () => new Intl.DateTimeFormat('en-CA', {timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateLabel = value => value ? new Intl.DateTimeFormat('en-GB', {day:'numeric',month:'short'}).format(new Date(value.slice(0,10)+'T12:00:00Z')) : 'Unscheduled';
const timestamp = value => value ? new Intl.DateTimeFormat('en-GB', {day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Dubai'}).format(new Date(value.includes('T') ? value : value.replace(' ','T')+'Z')) : '—';
const paths = {
  overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  jobs:'M9 5V3h6v2 M3 6h18v15H3z M3 11h18 M10 11v3h4v-3',
  schedule:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2 M8 18h2',
  approvals:'m8 12 3 3 5-6 M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z',
  evidence:'M3 4h18v16H3z M3 16l6-6 4 4 3-3 5 5 M16 8h.01',
  clients:'M3 21V7l9-4 9 4v14 M8 21v-5h8v5 M7 8h2 M15 8h2 M7 12h2 M15 12h2',
  team:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-4-4 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  reports:'M4 3v18h17 M8 16l4-5 4 2 5-7',
  search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
  plus:'M12 5v14 M5 12h14',arrow:'M7 17 17 7 M7 7h10v10',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',
  close:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',
  pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-3 3 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l3-3',
  logout:'M9 3H3v18h6 M9 12h12 m-5-5 5 5-5 5',filter:'M3 5h18 M6 12h12 M9 19h6',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',
  board:'M3 4h5v16H3z M10 4h5v10h-5z M17 4h5v13h-5z',sun:'M12 3v2 M12 19v2 M3 12h2 M19 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  alert:'M12 3 1 21h22z M12 9v5 M12 17h.01',more:'M5 12h.01 M12 12h.01 M19 12h.01',copy:'M8 8h13v13H8z M16 8V3H3v13h5',
  lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',mail:'M3 5h18v14H3z m0 0 9 7 9-7',phone:'M5 3h4l2 5-3 2a16 16 0 0 0 6 6l2-3 5 2v4c-1 6-20-6-16-16',
  file:'M4 2h10l6 6v14H4z M14 2v6h6 M8 13h8 M8 17h5',back:'M20 12H4 m6-6-6 6 6 6',refresh:'M20 8a9 9 0 1 0 1 7 M20 3v5h-5',upload:'M12 16V3 m-5 5 5-5 5 5 M4 16v5h16v-5',
  bolt:'M13 2 4 14h7l-1 8 10-13h-8z',grid:'M3 3h8v8H3z M15 3h6v8h-6z M3 15h8v6H3z M15 15h6v6h-6z',expand:'M4 9V4h5 M15 4h5v5 M20 15v5h-5 M9 20H4v-5'
};
function icon(name, cls='') {return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.jobs}"/></svg>`;}
const statusList=['Scheduled','In progress','Awaiting approval','Completed','Issue reported'];
const statusClass = status => status.toLowerCase().replaceAll(' ','-');
const badge = status => `<span class="badge ${statusClass(status)}"><span class="status-dot"></span>${e(status)}</span>`;
const jobRef = job => `SP-${String(job.id).padStart(4,'0')}`;
const pct = job => Math.round((job.tasks?.filter(t=>t.done).length || 0) / (job.tasks?.length || 1) * 100);
let state={page:'Overview',user:null,jobs:[],team:[],query:'',city:'All regions',status:'All statuses',view:'board',period:'All time',selected:null,evidenceKind:'All evidence',scheduleOffset:0,teamFilter:'All roles'};
async function api(path, body) {const response=await fetch('/api'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw Error('The service returned an unexpected response.');}if(!response.ok)throw Error(data.error || 'Request failed');return data;}
let toastTimer;
function toast(message) {$('#toast').innerHTML=icon('check')+`<span>${e(message)}</span>`;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function showDialog(html, cls='') {const d=$('#modal');if(d.open)d.close();d.className=cls;d.innerHTML=`<button class="icon-button dialog-close" aria-label="Close dialog">${icon('close')}</button>${html}`;$('.dialog-close',d).onclick=()=>d.close();d.showModal();}
function closeDialog() {$('#modal').close();}
const empty = (title, description='Try changing your filters or creating a work order.') => `<div class="empty-state">${icon('jobs')}<h3>${e(title)}</h3><p>${e(description)}</p></div>`;
function scopedJobs() {return state.jobs.filter(job=>(state.city==='All regions'||job.city===state.city)&&(state.period!=='This month'||job.date?.slice(0,7)===dateKey().slice(0,7)));}
function filteredJobs() {return scopedJobs().filter(job=>(state.status==='All statuses'||job.status===state.status)&&[job.title,job.client,job.location,jobRef(job)].join(' ').toLowerCase().includes(state.query.toLowerCase()));}
function logo() {return `<span class="logo-mark"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M8 7h16v7H15v4h9v7H8v-7h9v-4H8z" fill="currentColor"/></svg></span><span class="logo-word">siteproof<span>FIELD OPERATIONS</span></span>`;}
async function refreshData() {const [list,team]=await Promise.all([api('/jobs'),api('/team')]);state.jobs=await Promise.all(list.map(job=>api('/jobs/'+job.id)));state.team=team;}
async function load() {state.user=await api('/me');await refreshData();render();}
function login() {app.innerHTML=`<main class="auth"><section class="auth-brand"><a class="brand" href="/">${logo()}</a><div class="auth-copy"><p class="eyebrow">SERVICE DELIVERY WORKSPACE</p><h1>Service records,<br><span>kept together.</span></h1><p>Manage work orders, site evidence and client approvals in one place.</p><div class="auth-diagram"><span>${icon('jobs')} Work order</span><i></i><span>${icon('evidence')} Evidence</span><i></i><span>${icon('approvals')} Sign-off</span></div></div><div class="auth-footer"><span>SITEPROOF</span><span>DUBAI · ABU DHABI</span></div></section><section class="auth-panel"><div><span class="eyebrow">SITEPROOF WORKSPACE</span><h2>Sign in to operations</h2><p>Enter your workspace credentials to continue.</p><form id="login-form"><label>Work email<input name="email" type="email" required autocomplete="username" placeholder="you@company.com"></label><label>Password<input name="password" type="password" required autocomplete="current-password" placeholder="Enter your password"></label><button class="button primary full">Enter workspace ${icon('arrow')}</button><p class="form-error" role="alert"></p></form><div class="auth-note">${icon('lock')}<span>Your session is secured and access is role-based.</span></div></div><small>SiteProof UAE / Work orders and client approvals</small></section></main>`;$('#login-form').onsubmit=async event=>{event.preventDefault();const button=$('button',event.target);button.disabled=true;try{await api('/login',Object.fromEntries(new FormData(event.target)));await load();}catch(error){$('.form-error').textContent=error.message;}finally{button.disabled=false;}};}
function nav() {const entries=[['Overview','overview'],['Jobs','jobs'],['Schedule','schedule'],['Approvals','approvals'],['Evidence','evidence'],['Clients','clients'],['Team','team'],['Reports','reports']];return entries.map(([name,svg],i)=>`${i===5?'<span class="nav-caption">ORGANISATION</span>':''}<button class="nav-item ${state.page===name?'active':''}" data-page="${name}" aria-label="${name==='Jobs'?'Work orders':name}" ${state.page===name?'aria-current="page"':''}>${icon(svg)}<span>${name==='Jobs'?'Work orders':name}</span>${name==='Approvals'?`<small class="nav-count">${state.jobs.filter(j=>j.status==='Awaiting approval').length}</small>`:''}</button>`).join('');}
function render() {const user=state.user;app.innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="/">${logo()}</a><button class="workspace-switch" id="workspace-info"><span class="workspace-logo">S</span><span><strong>SiteProof Services</strong><small>UAE workspace</small></span>${icon('down')}</button><span class="nav-caption">OPERATIONS</span><nav>${nav()}</nav><div class="sidebar-bottom"><div class="workspace-health"><span class="status-dot"></span><div><b>Single-company workspace</b><small>Service management</small></div></div><button class="user-menu" id="profile"><span class="avatar orange">${initials(user.name)}</span><span><b>${e(user.name)}</b><small>${user.role==='admin'?'Workspace administrator':'Field technician'}</small></span>${icon('more')}</button></div></aside><div class="app-main"><header class="topbar"><div class="breadcrumb"><span class="breadcrumb-icon">${icon('overview')}</span><span>Workspace</span>${icon('chevron')}<b>${state.page==='Jobs'?'Work orders':e(state.page)}</b></div><button class="command-trigger" id="command-search" aria-label="Search workspace">${icon('search')}<span>Search anything…</span><kbd>⌘ K</kbd></button><div class="topbar-end"><span class="time-zone">UAE <b>GMT+4</b></span><button class="icon-button" id="refresh" aria-label="Refresh workspace">${icon('refresh')}</button><button class="avatar orange" id="profile-top" aria-label="Open profile">${initials(user.name)}</button></div></header><main class="content" id="content">${content()}</main><footer class="app-footer"><span><span class="status-dot"></span> SITEPROOF / SERVICE WORKSPACE</span><span>All values in AED <i>·</i> UAE local time</span></footer></div></div>`;bindGlobal();bindContent();}
function pageHeading(title,subtitle,actions='') {return `<section class="page-heading"><div><div class="section-overline"><span></span>${state.page==='Overview'?'WORKSPACE':state.page.toUpperCase()}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></section>`;}
function createButton() {return state.user.role==='admin'?`<button class="button primary" data-create>${icon('plus')} Create work order</button>`:'';}
function regionFilter() {return `<label class="select-button">${icon('pin')}<select id="region-filter" aria-label="Filter service region">${['All regions',...new Set(state.jobs.map(j=>j.city))].map(city=>`<option ${state.city===city?'selected':''}>${e(city)}</option>`).join('')}</select>${icon('down')}</label>`;}
function periodFilter() {return `<label class="select-button">${icon('schedule')}<select id="period-filter" aria-label="Reporting period">${['All time','This month'].map(p=>`<option ${state.period===p?'selected':''}>${p}</option>`).join('')}</select>${icon('down')}</label>`;}
function metrics() {const jobs=scopedJobs(),active=jobs.filter(j=>['In progress','Scheduled'].includes(j.status)),review=jobs.filter(j=>j.status==='Awaiting approval'),approved=jobs.filter(j=>j.status==='Completed'),issues=jobs.filter(j=>j.status==='Issue reported');const list=[{label:'Active work orders',value:String(active.length).padStart(2,'0'),caption:`${jobs.filter(j=>j.status==='In progress').length} in field · ${jobs.filter(j=>j.status==='Scheduled').length} scheduled`,icon:'jobs',tone:'orange',tag:'DELIVERY'},{label:'Pending client approval',value:String(review.length).padStart(2,'0'),caption:`${currency(review.reduce((sum,j)=>sum+j.amount,0))} awaiting sign-off`,icon:'approvals',tone:'violet',tag:'REVIEW'},{label:'Approved scope value',value:currency(approved.reduce((sum,j)=>sum+j.amount,0)),caption:`${approved.length} completed work order${approved.length===1?'':'s'}`,icon:'reports',tone:'blue',tag:'APPROVED'},{label:'Open issues',value:String(issues.length).padStart(2,'0'),caption:issues.length?'Requires team follow-up':'No unresolved client issues',icon:'alert',tone:'red',tag:'ATTENTION'}];return `<section class="metrics" aria-label="Workspace metrics">${list.map(m=>`<article class="metric ${m.tone}"><div class="metric-top"><span>${m.label}</span><span class="metric-symbol">${icon(m.icon)}</span></div><strong>${m.value}</strong><div class="metric-bottom"><span>${m.caption}</span><span class="metric-tick"></span></div></article>`).join('')}</section>`;}
function operationalPanel() {const jobs=scopedJobs(),cities=['Abu Dhabi','Dubai','Sharjah','Ajman'],pctComplete=Math.round(jobs.filter(j=>j.status==='Completed').length/(jobs.length||1)*100);return `<section class="operations-grid"><article class="region-panel"><div class="region-header"><div><span class="eyebrow">REGIONAL OPERATIONS</span><h2>Work by service area</h2></div><span class="region-tag"><span></span> UAE SERVICE NETWORK</span></div><div class="region-summary"><p>Jobs are grouped by the service area entered in each work order.</p><div><span>Dubai</span><span>Abu Dhabi</span></div><small>Use the region filter to review one area.</small></div><div class="region-cities">${cities.slice(0,2).map(city=>{const js=jobs.filter(j=>j.city===city);return `<button data-region="${city}"><span class="city-symbol">${icon('pin')}</span><span><strong>${city}</strong><small>${js.filter(j=>j.status!=='Completed').length} open work orders</small></span><b>${String(js.length).padStart(2,'0')}</b>${icon('arrow')}</button>`}).join('')}</div></article><article class="panel delivery-panel"><div class="panel-heading"><div><h2>Delivery health</h2><p>Current workspace snapshot</p></div>${icon('reports')}</div><div class="completion-ring"><svg viewBox="0 0 160 160" aria-label="${pctComplete}% jobs completed"><circle class="ring-track" cx="80" cy="80" r="64"/><circle class="ring-value" cx="80" cy="80" r="64" stroke-dasharray="${pctComplete*4.021} 402.1"/></svg><div><b>${pctComplete}<span>%</span></b><small>COMPLETION</small></div></div><div class="delivery-legend">${[['Completed','Completed'],['In progress','In field'],['Awaiting approval','Client review']].map(([status,label])=>`<div><span class="legend-dot ${statusClass(status)}"></span><span>${label}</span><b>${jobs.filter(j=>j.status===status).length}</b></div>`).join('')}</div><button class="panel-bottom-link" data-page="Reports">Open operations report ${icon('arrow')}</button></article></section>`;}
function queuePanel() {const queue=scopedJobs().filter(j=>['Awaiting approval','Issue reported'].includes(j.status));return `<section class="panel queue-panel"><div class="panel-heading"><div><h2>Action queue <span class="count-badge">${queue.length}</span></h2><p>Decisions and exceptions that need a next step.</p></div><button class="button ghost small" data-page="Approvals">Review all ${icon('arrow')}</button></div><div class="queue-grid">${queue.slice(0,3).map(job=>`<button class="queue-item" data-job="${job.id}"><span class="queue-symbol ${job.status==='Issue reported'?'red':'violet'}">${icon(job.status==='Issue reported'?'alert':'approvals')}</span><div><span class="micro-label">${jobRef(job)} / ${job.status==='Issue reported'?'EXCEPTION':'CLIENT REVIEW'}</span><b>${e(job.title)}</b><small>${e(job.client)} <i>·</i> ${currency(job.amount)}</small></div>${icon('chevron')}</button>`).join('')||empty('No pending actions','The delivery queue is clear.')}</div></section>`;}
function jobTable(jobs) {return jobs.length?`<div class="table-wrap"><table class="job-table"><thead><tr><th>WORK ORDER</th><th>CLIENT / SITE</th><th>ASSIGNEE</th><th>STATUS</th><th>PROGRESS</th><th>SCOPE VALUE</th><th></th></tr></thead><tbody>${jobs.map(job=>`<tr><td><button class="job-cell" data-job="${job.id}"><span class="job-type">${icon(categoryIcon(job.category))}</span><span><small>${jobRef(job)}</small><b>${e(job.title)}</b></span></button></td><td><b>${e(job.client)}</b><small>${e(job.location)}, ${e(job.city)}</small></td><td><span class="assignee"><span class="avatar tiny">${initials(job.technician_name)}</span>${e(job.technician_name||'Unassigned')}</span></td><td>${badge(job.status)}</td><td><span class="table-progress"><progress value="${pct(job)}" max="100"></progress><small>${pct(job)}%</small></span></td><td class="numeric">${currency(job.amount)}</td><td><button class="icon-button" data-job="${job.id}" aria-label="Open ${e(job.title)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No matching work orders');}
function categoryIcon(category='') {return category.includes('CCTV')?'approvals':category.includes('network')||category.includes('IT')?'bolt':category.includes('AC')?'sun':'jobs';}
function jobBoard(jobs) {return `<div class="kanban">${statusList.map(status=>{const list=jobs.filter(j=>j.status===status);return `<section class="kanban-column"><div class="column-heading"><span class="legend-dot ${statusClass(status)}"></span><h3>${status==='Awaiting approval'?'Client review':status==='Issue reported'?'Issues':status}</h3><span>${list.length}</span></div><div class="column-value">${currency(list.reduce((sum,j)=>sum+j.amount,0))}<small>scope value</small></div><div class="kanban-stack">${list.map(job=>`<button class="kanban-card" data-job="${job.id}"><div class="card-top"><span>${jobRef(job)}</span>${icon(categoryIcon(job.category))}</div><h3>${e(job.title)}</h3><p>${e(job.client)}</p><span class="card-location">${icon('pin')}${e(job.city)} <i>·</i> ${e(job.location)}</span><div class="card-progress"><progress max="100" value="${pct(job)}"></progress><small>${job.tasks.filter(t=>t.done).length}/${job.tasks.length} tasks</small></div><div class="card-bottom"><span class="avatar tiny">${initials(job.technician_name)}</span><span>${icon('schedule')}${dateLabel(job.date)}</span><b>${currency(job.amount)}</b></div><div class="card-proof">${icon('evidence')} ${job.evidence.length} evidence ${job.variations.some(v=>v.status==='Pending')?'<span class="variation-pip">Scope change pending</span>':''}</div></button>`).join('')||'<div class="empty-column">No work orders</div>'}</div></section>`}).join('')}</div>`;}
function jobsToolbar() {return `<div class="jobs-toolbar"><div class="search-field">${icon('search')}<input id="job-search" aria-label="Search work orders" placeholder="Search by title, client or reference…" value="${e(state.query)}"><kbd>/</kbd></div>${regionFilter()}<label class="select-button">${icon('filter')}<select id="status-filter" aria-label="Filter status">${['All statuses',...statusList].map(s=>`<option ${state.status===s?'selected':''}>${s}</option>`).join('')}</select>${icon('down')}</label><div class="view-switch" aria-label="Work order view"><button data-view="board" class="${state.view==='board'?'active':''}" aria-label="Board view" aria-pressed="${state.view==='board'}">${icon('board')}</button><button data-view="list" class="${state.view==='list'?'active':''}" aria-label="Table view" aria-pressed="${state.view==='list'}">${icon('list')}</button></div></div>`;}
function content() {
  if(state.selected)return detailPage();
  if(state.page==='Overview')return `${pageHeading('Operations overview','Review scheduled jobs, work in progress and client approvals.',periodFilter()+regionFilter()+createButton())}${metrics()}${operationalPanel()}${queuePanel()}<section class="panel"><div class="panel-heading"><div><h2>Work order register</h2><p>${scopedJobs().length} records across your service network</p></div><button class="button ghost small" data-page="Jobs">View all work orders ${icon('arrow')}</button></div>${jobTable(scopedJobs().slice(0,5))}</section>`;
  if(state.page==='Jobs')return `${pageHeading('Work orders','Plan the work. Capture the proof. Close the loop.',`<button class="button secondary" id="export">${icon('download')} Export</button>${createButton()}`)}<div class="page-tabs"><button class="active">All work orders <span>${state.jobs.length}</span></button><button id="my-jobs">Assigned to me <span>${state.jobs.filter(j=>j.technician===state.user.id).length}</span></button><div class="tabs-right">${icon('jobs')} ${filteredJobs().length} visible records</div></div>${jobsToolbar()}<div id="job-results">${state.view==='board'?jobBoard(filteredJobs()):`<section class="panel">${jobTable(filteredJobs())}</section>`}</div>`;
  if(state.page==='Schedule')return schedulePage();
  if(state.page==='Approvals')return approvalsPage();
  if(state.page==='Evidence')return evidencePage();
  if(state.page==='Clients')return clientsPage();
  if(state.page==='Team')return teamPage();
  return reportsPage();
}
function schedulePage() {const start=new Date(dateKey()+'T12:00:00Z');start.setUTCDate(start.getUTCDate()+state.scheduleOffset*7);const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setUTCDate(start.getUTCDate()+i);return {key:d.toISOString().slice(0,10),day:d.toLocaleDateString('en-GB',{weekday:'short',timeZone:'Asia/Dubai'}),number:d.getUTCDate()};});const jobs=scopedJobs();return `${pageHeading('Dispatch schedule','See the week ahead and open each site’s work order.',createButton())}<div class="schedule-toolbar"><div><h2>${dateLabel(days[0].key)} — ${dateLabel(days[6].key)} <span>${start.getUTCFullYear()}</span></h2><p>Scheduled visits · UAE local dates</p></div><div class="heading-actions">${regionFilter()}<button class="button secondary small" id="week-today">Today</button><div class="view-switch"><button id="week-prev" aria-label="Previous week">${icon('back')}</button><button id="week-next" aria-label="Next week">${icon('chevron')}</button></div></div></div><div class="week-grid">${days.map(day=>{const list=jobs.filter(j=>j.date===day.key);return `<section class="day-column ${day.key===dateKey()?'today':''}"><div class="day-heading"><span>${day.day}</span><b>${day.number}</b><small>${list.length} visits</small></div><div class="day-jobs">${list.map(job=>`<button class="schedule-job ${statusClass(job.status)}" data-job="${job.id}"><span class="micro-label">${jobRef(job)}</span><b>${e(job.title)}</b><small>${icon('pin')}${e(job.city)}</small><span class="assignee"><span class="avatar tiny">${initials(job.technician_name)}</span>${e(job.technician_name?.split(' ')[0]||'Unassigned')}</span></button>`).join('')||'<div class="day-empty">No visits</div>'}</div></section>`}).join('')}</div><div class="section-title"><h2>Scheduled site visits</h2><span>${jobs.filter(j=>j.status!=='Completed').length} open</span></div><div class="panel">${jobs.filter(j=>j.status!=='Completed').map(job=>`<div class="visit-row"><div class="visit-date"><b>${new Date(job.date+'T12:00:00Z').getUTCDate()}</b><span>${new Date(job.date+'T12:00:00Z').toLocaleDateString('en-GB',{month:'short'})}</span></div><div class="visit-info"><button class="text-button" data-job="${job.id}">${e(job.title)}</button><small>${e(job.location)}, ${e(job.city)} · ${e(job.technician_name)}</small></div>${badge(job.status)}<a class="button secondary small" href="${mapsLink(job)}" target="_blank" rel="noreferrer">${icon('pin')} Directions ${icon('arrow')}</a></div>`).join('')||empty('No open visits')}</div>`;}
function mapsLink(job) {return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(job.location+' '+job.city+' UAE');}
function approvalsPage() {const jobs=scopedJobs(),pending=jobs.filter(j=>j.status==='Awaiting approval'),issues=jobs.filter(j=>j.status==='Issue reported');return `${pageHeading('Client review desk','A controlled handover for every delivered work order.',regionFilter())}<div class="review-stats"><div><span class="review-stat-icon violet">${icon('approvals')}</span><span><small>Awaiting sign-off</small><b>${pending.length} work orders</b></span><strong>${currency(pending.reduce((s,j)=>s+j.amount,0))}</strong></div><div><span class="review-stat-icon red">${icon('alert')}</span><span><small>Client exceptions</small><b>${issues.length} open issues</b></span><strong>Action required</strong></div></div><div class="section-title"><h2>Pending approvals</h2><span>Review evidence before sharing</span></div><div class="approval-grid">${pending.map(job=>`<article class="panel approval-card"><div class="approval-top"><span class="micro-label">${jobRef(job)} · ${e(job.city)}</span>${badge(job.status)}</div><h2>${e(job.title)}</h2><p>${e(job.client)} · ${e(job.location)}</p><div class="approval-readiness"><div>${icon('check')}<b>${job.tasks.filter(t=>t.done).length}/${job.tasks.length}</b><span>Tasks done</span></div><div>${icon('evidence')}<b>${job.evidence.length}</b><span>Evidence records</span></div><div>${icon('file')}<b>${job.variations.filter(v=>v.status==='Pending').length}</b><span>Scope decisions</span></div></div><div class="approval-value"><span>Original scope value</span><b>${currency(job.amount)}</b></div><div class="approval-actions"><button class="button secondary" data-job="${job.id}">Review record ${icon('arrow')}</button><button class="button primary" data-share="${job.id}">${icon('link')} Client portal</button></div></article>`).join('')||empty('No work awaiting approval','Completed checklists and evidence will appear here when submitted.')}</div><div class="section-title"><h2>Exceptions & reported issues</h2><span>${issues.length} records</span></div><section class="panel">${jobTable(issues)}</section>`;}
function evidencePage() {const records=scopedJobs().flatMap(job=>job.evidence.map(record=>({...record,job}))),filtered=records.filter(record=>(state.evidenceKind==='All evidence'||record.kind===state.evidenceKind)&&[record.note,record.job.title,record.job.client].join(' ').toLowerCase().includes(state.query.toLowerCase()));return `${pageHeading('Evidence library','A traceable record of what was inspected, installed and handed over.',regionFilter())}<div class="evidence-toolbar"><div class="page-tabs">${['All evidence','Before','After','Inspection'].map(kind=>`<button data-evidence-kind="${kind}" class="${state.evidenceKind===kind?'active':''}">${kind}<span>${records.filter(r=>kind==='All evidence'||r.kind===kind).length}</span></button>`).join('')}</div><div class="search-field">${icon('search')}<input id="evidence-search" aria-label="Search evidence" placeholder="Search records…" value="${e(state.query)}"></div></div><div class="library-grid" id="library-results">${evidenceCards(filtered)}</div>`;}
function evidenceCards(records) {return records.length?records.map(record=>`<button class="library-card" data-evidence-job="${record.job.id}" data-evidence-id="${record.id}"><div class="library-preview ${record.image?'':'record-preview'}">${record.image?`<img src="${record.image}" alt="${e(record.kind)} evidence for ${e(record.job.title)}" loading="lazy">`:`<div class="record-sheet">${icon('file')}<span>FIELD INSPECTION RECORD</span><b>${e(record.job.category)}</b><i></i><i></i><i></i><span class="record-stamp">${icon('check')} RECORDED</span></div>`}<span class="evidence-kind">${e(record.kind)}</span><span class="preview-expand">${icon('expand')}</span></div><div class="library-info"><span class="micro-label">${jobRef(record.job)}</span><h3>${e(record.note)}</h3><p>${e(record.job.title)}</p><div><span>${e(record.job.city)}</span><small>${timestamp(record.created)}</small></div></div></button>`).join(''):empty('No evidence matches this view','Add photos or inspection notes from a work order.');}
function clientsPage() {const jobs=scopedJobs(),names=[...new Set(jobs.map(job=>job.client))];return `${pageHeading('Client directory','Service relationships with a complete work history.',regionFilter())}<div class="client-directory">${names.map((name,index)=>{const list=jobs.filter(j=>j.client===name),job=list[0];return `<article class="panel directory-card"><div class="directory-top"><span class="company-avatar tone-${index%3}">${initials(name)}</span><span class="client-code">CL-${String(index+1).padStart(3,'0')}</span></div><h2>${e(name)}</h2><p>${icon('pin')}${e(job.location)}, ${e(job.city)}</p><div class="directory-metrics"><div><small>WORK ORDERS</small><b>${list.length}</b></div><div><small>CONTRACTED SCOPE</small><b>${currency(list.reduce((s,j)=>s+j.amount,0))}</b></div></div><div class="directory-status"><span class="status-dot"></span>${list.filter(j=>j.status!=='Completed').length} open work orders</div><button class="panel-bottom-link" data-client="${e(name)}">View client record ${icon('arrow')}</button></article>`}).join('')||empty('No clients yet')}</div>`;}
function teamPage() {const team=state.team.filter(member=>state.teamFilter==='All roles'||member.role===state.teamFilter);return `${pageHeading('People & assignments','Accountability starts with a clear owner for every work order.',state.user.role==='admin'?`<button class="button primary" id="add-team">${icon('plus')} Add member</button>`:'')}<div class="page-tabs">${['All roles','admin','technician'].map(role=>`<button data-role="${role}" class="${state.teamFilter===role?'active':''}">${role==='All roles'?role:role==='admin'?'Administrators':'Technicians'}<span>${state.team.filter(m=>role==='All roles'||m.role===role).length}</span></button>`).join('')}</div><div class="team-grid">${team.map(member=>{const jobs=state.jobs.filter(j=>j.technician===member.id),active=jobs.filter(j=>j.status!=='Completed');return `<article class="panel member-card"><div class="member-top"><span class="avatar large ${member.role==='admin'?'orange':'purple'}">${initials(member.name)}</span><span class="role-pill">${member.role==='admin'?'ADMIN':'TECHNICIAN'}</span></div><h2>${e(member.name)}</h2><p>${e(member.email)}</p><div class="member-load"><span>Assignment load</span><b>${active.length} open / ${jobs.length} total</b></div><progress value="${active.length}" max="${Math.max(1,state.jobs.filter(j=>j.status!=='Completed').length)}"></progress><div class="member-footer"><span>${icon('approvals')} ${jobs.filter(j=>j.status==='Completed').length} completed</span><button class="text-button" data-assignee="${member.id}">View assignments ${icon('arrow')}</button></div></article>`}).join('')}</div>`;}
function reportsPage() {const jobs=scopedJobs(),completed=jobs.filter(j=>j.status==='Completed'),total=jobs.reduce((s,j)=>s+j.amount,0);return `${pageHeading('Operations intelligence','Delivery metrics calculated directly from your work order records.',periodFilter()+regionFilter()+`<button class="button secondary" id="export">${icon('download')} Export register</button>`)}${metrics()}<div class="report-grid"><section class="panel"><div class="panel-heading"><div><h2>Delivery pipeline</h2><p>Open scope by operational stage</p></div>${icon('reports')}</div><div class="pipeline-bars">${statusList.map(status=>{const js=jobs.filter(j=>j.status===status);return `<div><div><span class="legend-dot ${statusClass(status)}"></span><label>${status}</label><b>${js.length}</b><small>${currency(js.reduce((s,j)=>s+j.amount,0))}</small></div><progress value="${js.length}" max="${Math.max(1,jobs.length)}" class="${statusClass(status)}"></progress></div>`}).join('')}</div></section><section class="panel"><div class="panel-heading"><div><h2>Regional distribution</h2><p>Contracted scope by service region</p></div>${icon('pin')}</div><div class="regional-report">${[...new Set(jobs.map(j=>j.city))].map((city,i)=>{const js=jobs.filter(j=>j.city===city),value=js.reduce((s,j)=>s+j.amount,0);return `<div><span class="region-number">0${i+1}</span><div><h3>${e(city)}</h3><p>${js.length} work orders · ${js.filter(j=>j.status==='Completed').length} completed</p><progress value="${value}" max="${total||1}"></progress></div><b>${currency(value)}</b></div>`}).join('')}</div><div class="report-summary"><span>Total contracted scope</span><b>${currency(total)}</b></div></section></div><div class="report-grid"><section class="panel"><div class="panel-heading"><div><h2>Evidence coverage</h2><p>Documented work across the register</p></div>${icon('evidence')}</div><div class="coverage-stats"><div><b>${jobs.reduce((s,j)=>s+j.evidence.length,0)}</b><span>Evidence records</span></div><div><b>${Math.round(jobs.filter(j=>j.evidence.length).length/(jobs.length||1)*100)}%</b><span>Jobs with evidence</span></div><div><b>${jobs.reduce((s,j)=>s+j.tasks.filter(t=>t.done).length,0)}</b><span>Checklist items complete</span></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Scope change control</h2><p>Client decisions on additional work</p></div>${icon('file')}</div><div class="coverage-stats">${['Pending','Approved','Declined'].map(status=>`<div><b>${jobs.reduce((s,j)=>s+j.variations.filter(v=>v.status===status).length,0)}</b><span>${status} changes</span></div>`).join('')}</div></section></div><div class="report-disclaimer">${icon('file')}<p>Scope values reflect agreed work, not collected revenue. Client names are self-declared. Completion is based on recorded client decisions.</p></div>`;}
function workflowStepper(job) {const stages=[['Created','jobs'],['In field','bolt'],['Client review','approvals'],['Completed','check']],stage=job.status==='Completed'?3:job.status==='Awaiting approval'?2:job.status==='In progress'||job.status==='Issue reported'?1:0;return `<div class="workflow-stepper">${stages.map(([label,i],index)=>`<div class="workflow-step ${index<stage?'done':''} ${index===stage?'current':''}"><span>${icon(index<stage?'check':i)}</span><div><small>0${index+1}</small><b>${label}</b></div>${index===stage?'<em>CURRENT</em>':''}</div>`).join('')}</div>`;}
function detailPage() {const job=state.selected,locked=['Completed','Awaiting approval'].includes(job.status),approvedExtra=job.variations.filter(v=>v.status==='Approved').reduce((s,v)=>s+v.amount,0);return `<div class="detail-breadcrumb"><button class="text-button" id="back">${icon('back')} Work orders</button><span>/</span><span>${jobRef(job)}</span></div><section class="detail-header"><div><div class="detail-labels"><span class="reference-label">${jobRef(job)}</span><span>${e(job.category)}</span></div><h1>${e(job.title)}</h1><p>${icon('clients')}${e(job.client)} <span>·</span>${icon('pin')}${e(job.location)}, ${e(job.city)}</p></div><div>${badge(job.status)}</div></section><div class="detail-toolbar"><div><button class="button secondary small" id="share">${icon('link')} Client portal</button><button class="button secondary small" id="handover">${icon('download')} Handover PDF</button><a class="button ghost small" href="${mapsLink(job)}" target="_blank" rel="noreferrer">${icon('pin')} Directions ${icon('arrow')}</a></div><label class="select-button status-action">${icon('refresh')}<select id="job-status" aria-label="Update work order status"><option value="">Update status</option>${['Scheduled','In progress','Awaiting approval'].map(s=>`<option ${s===job.status?'disabled':''}>${s}</option>`).join('')}</select>${icon('down')}</label></div>${workflowStepper(job)}<div class="detail-layout"><div class="detail-primary"><section class="panel"><div class="panel-heading"><h2>Scope of work</h2><span class="micro-label">ORIGINAL AGREEMENT</span></div><div class="scope-body"><p>${e(job.scope)}</p><div class="scope-metadata"><div><small>ASSIGNED TECHNICIAN</small><span class="assignee"><span class="avatar tiny">${initials(job.technician_name)}</span><b>${e(job.technician_name)}</b></span></div><div><small>SCHEDULED VISIT</small><b>${icon('schedule')}${dateLabel(job.date)}</b></div><div><small>ORIGINAL SCOPE</small><strong>${currency(job.amount)}</strong></div></div></div></section><section class="panel"><div class="panel-heading"><h2>Delivery checklist <span class="count-badge">${job.tasks.filter(t=>t.done).length}/${job.tasks.length}</span></h2><span class="completion-label">${pct(job)}% complete</span></div><progress class="checklist-progress" max="100" value="${pct(job)}"></progress><div class="checklist">${job.tasks.map((task,i)=>`<label class="checklist-row ${task.done?'checked':''}"><input type="checkbox" data-task="${task.id}" ${task.done?'checked':''} ${locked?'disabled':''}><span class="custom-check">${icon('check')}</span><span><b>${e(task.label)}</b><small>DELIVERY REQUIREMENT 0${i+1}</small></span>${task.done?'<em>Complete</em>':''}</label>`).join('')}</div>${locked?`<div class="panel-footnote">${icon('lock')} Reopen the work order to edit delivery records.</div>`:''}</section><section class="panel"><div class="panel-heading"><div><h2>Field evidence <span class="count-badge">${job.evidence.length}</span></h2><p>Before, after and inspection records</p></div><button class="button secondary small" id="add-evidence" ${locked?'disabled':''}>${icon('plus')} Add evidence</button></div><div class="job-evidence-grid">${job.evidence.length?evidenceCards(job.evidence.map(record=>({...record,job}))):empty('No evidence captured','Add site photos or a detailed inspection note.')}</div></section><section class="panel"><div class="panel-heading"><div><h2>Scope change requests</h2><p>Additional work requires a separate client decision.</p></div>${state.user.role==='admin'?`<button class="button ghost small" id="add-variation" ${locked?'disabled':''}>${icon('plus')} Request change</button>`:''}</div>${job.variations.map(v=>`<div class="variation-row"><span class="variation-icon">${icon('file')}</span><div><b>${e(v.description)}</b><small>ADDITIONAL SCOPE</small></div><strong>${currency(v.amount)}</strong>${badge(v.status)}</div>`).join('')||'<div class="panel-footnote">No variations to the original scope have been requested.</div>'}</section></div><div class="detail-secondary"><section class="panel handover-card"><div class="handover-icon">${icon('approvals')}</div><span class="eyebrow">HANDOVER READINESS</span><h2>${pct(job)===100&&job.evidence.length?'Ready for review.':'Ready for handover?'}</h2><p>Complete the delivery requirements before requesting client sign-off.</p><div class="readiness-row"><span>${icon('check')} Checklist</span><b>${job.tasks.filter(t=>t.done).length}/${job.tasks.length}</b></div><div class="readiness-row"><span>${icon('evidence')} Site evidence</span><b>${job.evidence.length?'Recorded':'Missing'}</b></div><div class="readiness-row"><span>${icon('file')} Scope decisions</span><b>${job.variations.filter(v=>v.status==='Pending').length} pending</b></div><button class="button primary full" id="submit-review" ${locked?'disabled':''}>Submit for client review ${icon('arrow')}</button><button class="button ghost full small" id="copy-summary">${icon('copy')} Copy client summary</button></section><section class="panel financial-card"><div class="panel-heading"><h2>Commercial summary</h2></div><div class="financial-body"><div><span>Original scope</span><b>${currency(job.amount)}</b></div><div><span>Approved changes</span><b>${currency(approvedExtra)}</b></div><div class="financial-total"><span>Total agreed scope</span><b>${currency(job.amount+approvedExtra)}</b></div><small>Excludes pending changes. Not a tax invoice.</small></div></section><section class="panel activity-card"><div class="panel-heading"><h2>Activity log</h2><span class="micro-label">${job.activity.length} EVENTS</span></div><div class="timeline">${job.activity.map(a=>`<div class="timeline-event"><span>${icon(a.message.includes('approved')?'check':a.message.includes('evidence')?'evidence':'clock')}</span><div><b>${e(a.message)}</b><p>${e(a.actor)}</p><small>${timestamp(a.created)} GST</small></div></div>`).join('')||'<p class="muted">No activity yet.</p>'}</div></section>${job.approvals.map(a=>`<section class="panel decision-record ${a.decision==='issue'?'issue':''}">${icon(a.decision==='approve'?'approvals':'alert')}<h3>${a.decision==='approve'?'Client approval recorded':'Client issue recorded'}</h3><p>${e(a.comment||'No comment provided.')}</p><b>${e(a.name)}</b><small>${timestamp(a.created)} GST</small></section>`).join('')}</div></div>`;}
function bindGlobal() {
  $$('[data-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.page));
  $('#workspace-info').onclick=()=>showDialog(`<span class="dialog-eyebrow">WORKSPACE</span><h2>SiteProof Services</h2><p>Single-company field operations workspace for the United Arab Emirates.</p><div class="info-grid"><div><small>WORK ORDERS</small><b>${state.jobs.length}</b></div><div><small>TEAM MEMBERS</small><b>${state.team.length}</b></div></div><p>Work order access is determined by your assigned role. Administrators manage the workspace; technicians work on their assignments.</p><button class="button secondary full" id="info-close">Return to workspace</button>`);$('#workspace-info').addEventListener('click',()=>{$('#info-close').onclick=closeDialog;});
  const profile=()=>{showDialog(`<span class="avatar large orange">${initials(state.user.name)}</span><h2>${e(state.user.name)}</h2><p>${e(state.user.email||'')}</p><span class="role-pill">${e(state.user.role).toUpperCase()}</span><hr><p>Signed in to the SiteProof Services workspace.</p><button class="button secondary full" id="logout">${icon('logout')} Sign out</button>`);$('#logout').onclick=async()=>{await api('/logout',{});closeDialog();login();};};$('#profile').onclick=profile;$('#profile-top').onclick=profile;
  $('#command-search').onclick=commandPalette;
  $('#refresh').onclick=async()=>{try{await refreshData();if(state.selected)state.selected=state.jobs.find(j=>j.id===state.selected.id);render();toast('Workspace refreshed');}catch(error){toast(error.message);}};
  $$('[data-create]').forEach(button=>button.onclick=createJob);
  $('#region-filter')?.addEventListener('change',event=>{state.city=event.target.value;render();});$('#period-filter')?.addEventListener('change',event=>{state.period=event.target.value;render();});
  $$('[data-region]').forEach(button=>button.onclick=()=>{state.city=button.dataset.region;navigate('Jobs');});
  bindJobLinks();
}
function navigate(page) {state.page=page;state.selected=null;state.query='';state.status='All statuses';render();window.scrollTo({top:0,behavior:'instant'});}
function bindJobLinks(root=document) {$$('[data-job]',root).forEach(button=>button.onclick=()=>openJob(+button.dataset.job));$$('[data-share]',root).forEach(button=>button.onclick=()=>shareJob(state.jobs.find(j=>j.id===+button.dataset.share)));$$('[data-evidence-job]',root).forEach(button=>button.onclick=()=>openEvidence(+button.dataset.evidenceJob,+button.dataset.evidenceId));}
async function openJob(id) {try{state.selected=await api('/jobs/'+id);state.page='Jobs';render();window.scrollTo({top:0,behavior:'instant'});}catch(error){toast(error.message);}}
function bindContent() {
  $('#export')?.addEventListener('click',exportCSV);
  $('#job-search')?.addEventListener('input',event=>{state.query=event.target.value;refreshJobResults();});
  $('#status-filter')?.addEventListener('change',event=>{state.status=event.target.value;refreshJobResults();});
  $$('[data-view]').forEach(button=>button.onclick=()=>{state.view=button.dataset.view;render();});
  $('#my-jobs')?.addEventListener('click',()=>showAssignments(state.user.id));
  $('#week-prev')?.addEventListener('click',()=>{state.scheduleOffset--;render();});$('#week-next')?.addEventListener('click',()=>{state.scheduleOffset++;render();});$('#week-today')?.addEventListener('click',()=>{state.scheduleOffset=0;render();});
  $$('[data-evidence-kind]').forEach(button=>button.onclick=()=>{state.evidenceKind=button.dataset.evidenceKind;render();});
  $('#evidence-search')?.addEventListener('input',event=>{state.query=event.target.value;const records=scopedJobs().flatMap(job=>job.evidence.map(record=>({...record,job}))).filter(record=>(state.evidenceKind==='All evidence'||record.kind===state.evidenceKind)&&[record.note,record.job.title,record.job.client].join(' ').toLowerCase().includes(state.query.toLowerCase()));$('#library-results').innerHTML=evidenceCards(records);bindJobLinks($('#library-results'));});
  $$('[data-client]').forEach(button=>button.onclick=()=>clientRecord(button.dataset.client));$$('[data-role]').forEach(button=>button.onclick=()=>{state.teamFilter=button.dataset.role;render();});$$('[data-assignee]').forEach(button=>button.onclick=()=>showAssignments(+button.dataset.assignee));$('#add-team')?.addEventListener('click',addTeamMember);
  if(state.selected)bindDetail();
}
function refreshJobResults() {$('#job-results').innerHTML=state.view==='board'?jobBoard(filteredJobs()):`<section class="panel">${jobTable(filteredJobs())}</section>`;bindJobLinks($('#job-results'));const count=$('.tabs-right');if(count)count.innerHTML=icon('jobs')+` ${filteredJobs().length} visible records`;}
function clientRecord(name) {const jobs=state.jobs.filter(j=>j.client===name),job=jobs[0];showDialog(`<span class="dialog-eyebrow">CLIENT RECORD</span><h2>${e(name)}</h2><p>${e(job.location)}, ${e(job.city)}</p>${job.email?`<a class="contact-link" href="mailto:${e(job.email)}">${icon('mail')}${e(job.email)}</a>`:''}${job.phone?`<p class="contact-link">${icon('phone')}${e(job.phone)}</p>`:''}<div class="info-grid"><div><small>WORK ORDERS</small><b>${jobs.length}</b></div><div><small>CONTRACTED SCOPE</small><b>${currency(jobs.reduce((s,j)=>s+j.amount,0))}</b></div></div><h3>Work history</h3><div class="dialog-job-list">${jobs.map(j=>`<button data-dialog-job="${j.id}"><div><small>${jobRef(j)}</small><b>${e(j.title)}</b></div>${badge(j.status)}${icon('arrow')}</button>`).join('')}</div>`);$$('[data-dialog-job]').forEach(b=>b.onclick=()=>{closeDialog();openJob(+b.dataset.dialogJob);});}
function showAssignments(id) {const member=state.team.find(t=>t.id===id),jobs=state.jobs.filter(j=>j.technician===id);showDialog(`<span class="dialog-eyebrow">ASSIGNMENT REGISTER</span><h2>${e(member?.name||'Team member')}</h2><p>${jobs.length} work orders assigned</p><div class="dialog-job-list">${jobs.map(j=>`<button data-dialog-job="${j.id}"><div><small>${jobRef(j)} / ${e(j.city)}</small><b>${e(j.title)}</b></div>${badge(j.status)}${icon('arrow')}</button>`).join('')||empty('No assigned work orders')}</div>`,'wide-dialog');$$('[data-dialog-job]').forEach(b=>b.onclick=()=>{closeDialog();openJob(+b.dataset.dialogJob);});}
function commandPalette() {showDialog(`<div class="command-input">${icon('search')}<input id="command-input" placeholder="Search work orders, clients or locations…" aria-label="Search workspace" autocomplete="off"><kbd>ESC</kbd></div><div id="command-results"></div><div class="command-footer">Search your work order register <span>↵ Open record</span></div>`,'command-dialog');const input=$('#command-input');const update=()=>{const jobs=state.jobs.filter(j=>[j.title,j.client,j.location,jobRef(j)].join(' ').toLowerCase().includes(input.value.toLowerCase())).slice(0,7);$('#command-results').innerHTML=`<span class="command-section-label">WORK ORDERS</span>${jobs.map(j=>`<button class="command-result" data-command-job="${j.id}"><span class="job-type">${icon(categoryIcon(j.category))}</span><span><b>${e(j.title)}</b><small>${jobRef(j)} · ${e(j.client)}</small></span>${badge(j.status)}${icon('arrow')}</button>`).join('')||empty('No matching records','Try a client name or reference.')}<span class="command-section-label">QUICK NAVIGATION</span><div class="command-pages">${['Overview','Jobs','Approvals','Evidence','Reports'].map(page=>`<button data-command-page="${page}">${e(page)} ${icon('arrow')}</button>`).join('')}</div>`;$$('[data-command-job]').forEach(b=>b.onclick=()=>{closeDialog();openJob(+b.dataset.commandJob);});$$('[data-command-page]').forEach(b=>b.onclick=()=>{closeDialog();navigate(b.dataset.commandPage);});};input.oninput=update;input.onkeydown=event=>{if(event.key==='Enter')$('[data-command-job]')?.click();};update();input.focus();}
document.addEventListener('keydown',event=>{if(!state.user)return;if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();commandPalette();}else if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)&&!$('#modal').open){event.preventDefault();commandPalette();}});
async function submitForm(event, path) {event.preventDefault();const button=$('button[type="submit"]',event.target);button.disabled=true;try{const result=await api(path,Object.fromEntries(new FormData(event.target)));closeDialog();await refreshData();if(state.selected)state.selected=state.jobs.find(j=>j.id===state.selected.id);render();toast('Record saved');return result;}catch(error){const errorBox=$('.form-error',event.target);if(errorBox)errorBox.textContent=error.message;else toast(error.message);}finally{button.disabled=false;}}
function createJob() {showDialog(`<span class="dialog-eyebrow">WORK ORDER / NEW</span><h2>Create work order</h2><p>Define the scope, assign an owner and schedule the visit.</p><form id="job-form"><label>Work order title <span>*</span><input name="title" required maxlength="200" placeholder="e.g. CCTV installation — Marina Heights"></label><div class="form-grid"><label>Client / company <span>*</span><input name="client" required maxlength="200" placeholder="Company or client name"></label><label>Client email<input name="email" type="email" placeholder="client@company.com"></label><label>Contact number<input name="phone" type="tel" placeholder="+971"></label><label>Service region<select name="city"><option>Dubai</option><option>Abu Dhabi</option><option>Sharjah</option><option>Ajman</option><option>Other</option></select></label><label>Site location <span>*</span><input name="location" required placeholder="Building, district or address"></label><label>Service category<select name="category"><option>CCTV & security</option><option>IT & networking</option><option>AC maintenance</option><option>Electrical</option><option>Cleaning</option><option>Other</option></select></label><label>Scheduled visit <span>*</span><input name="date" type="date" required value="${dateKey()}"></label><label>Original scope value (AED) <span>*</span><input name="amount" type="number" required min="0" step="0.01" placeholder="0.00"></label></div><label>Assigned owner<select name="technician">${state.team.map(u=>`<option value="${u.id}" ${u.id===(state.team.find(m=>m.role==='technician')?.id||state.team[0]?.id)?'selected':''}>${e(u.name)} · ${e(u.role)}</option>`).join('')}</select></label><label>Scope of work <span>*</span><textarea name="scope" rows="4" required maxlength="2000" placeholder="Define deliverables, acceptance criteria and work boundaries."></textarea></label><p class="form-error" role="alert"></p><div class="form-footer"><span>Four delivery checklist items will be added.</span><button type="submit" class="button primary">Create work order ${icon('arrow')}</button></div></form>`,'wide-dialog');$('#job-form').onsubmit=event=>submitForm(event,'/jobs');}
function addTeamMember() {showDialog(`<span class="dialog-eyebrow">ORGANISATION / PEOPLE</span><h2>Add a team member</h2><p>Grant access to the single-company workspace.</p><form id="team-form"><label>Full name<input name="name" required maxlength="200"></label><label>Work email<input name="email" type="email" required></label><label>Initial password<input name="password" type="password" required minlength="12" autocomplete="new-password"><small>At least 12 characters. Share privately with the member.</small></label><label>Workspace role<select name="role"><option value="technician">Technician — assigned work orders</option><option value="admin">Administrator — full workspace</option></select></label><p class="form-error" role="alert"></p><button class="button primary full" type="submit">Create member ${icon('arrow')}</button></form>`);$('#team-form').onsubmit=event=>submitForm(event,'/team');}
async function updateJob(action, body) {try{const job=await api('/jobs/'+state.selected.id+'/'+action,body);state.selected=job;const index=state.jobs.findIndex(j=>j.id===job.id);if(index>=0)state.jobs[index]=job;render();return true;}catch(error){toast(error.message);render();return false;}}
function bindDetail() {const job=state.selected;$('#back').onclick=()=>{state.selected=null;render();};$('#job-status').onchange=event=>{if(event.target.value)updateJob('status',{status:event.target.value});};$$('[data-task]').forEach(input=>input.onchange=()=>updateJob('task',{id:+input.dataset.task,done:input.checked}));$('#submit-review').onclick=()=>updateJob('status',{status:'Awaiting approval'});$('#share').onclick=()=>shareJob(job);$('#handover').onclick=()=>printReport(job);$('#copy-summary').onclick=()=>copyText(summary(job));$('#add-evidence').onclick=()=>addEvidence(job);$('#add-variation')?.addEventListener('click',()=>addVariation(job));}
function summary(job) {return `${jobRef(job)} | ${job.title}\nClient: ${job.client}\nSite: ${job.location}, ${job.city}\nScope: ${job.scope}\nDelivery checklist: ${job.tasks.filter(t=>t.done).length}/${job.tasks.length} complete\nEvidence records: ${job.evidence.length}\nStatus: ${job.status}\nOriginal scope value: ${currency(job.amount)}\nApproved changes: ${currency(job.variations.filter(v=>v.status==='Approved').reduce((sum,v)=>sum+v.amount,0))}`;}
async function copyText(text) {try{await navigator.clipboard.writeText(text);toast('Copied to clipboard');}catch{showDialog(`<span class="dialog-eyebrow">COPY RECORD</span><h2>Copy the text below</h2><textarea rows="8" readonly>${e(text)}</textarea>`);$('#modal textarea').select();}}
function shareJob(job) {const link=location.origin+(window.SITEPROOF_DEMO?'/#/approve/':'/approve/')+job.token;showDialog(`<span class="dialog-eyebrow">CLIENT HANDOVER / ${jobRef(job)}</span><h2>Share the client review link</h2><p>The client can review scope, evidence and changes, then record their decision.</p><div class="share-summary">${icon('approvals')}<div><b>${e(job.title)}</b><small>${e(job.client)}</small></div>${badge(job.status)}</div><label>Client portal link<input readonly id="share-url" value="${e(link)}"></label><div class="share-actions"><button class="button primary" id="copy-link">${icon('copy')} Copy link</button><a class="button secondary" href="${e(link)}" target="_blank" rel="noreferrer">Open portal ${icon('arrow')}</a></div><div class="security-note">${icon('lock')}<p>Anyone with this link can access this work order. Share it only with authorised client contacts.${window.SITEPROOF_DEMO?' In this demo, the link works only in the same browser.':''}</p></div>${state.user.role==='admin'?`<div class="share-revoke"><p>Need to revoke previous access?</p><button class="text-button danger" id="rotate-link">Generate a new link ${icon('refresh')}</button></div>`:''}`);$('#copy-link').onclick=()=>copyText(link);$('#rotate-link')?.addEventListener('click',async()=>{try{const updated=await api('/jobs/'+job.id+'/share',{});const index=state.jobs.findIndex(j=>j.id===job.id);state.jobs[index]=updated;if(state.selected?.id===job.id)state.selected=updated;shareJob(updated);toast('Previous client link revoked');}catch(error){toast(error.message);}});}
function addEvidence(job) {showDialog(`<span class="dialog-eyebrow">FIELD RECORD / ${jobRef(job)}</span><h2>Capture site evidence</h2><p>A clear record helps the client understand exactly what was delivered.</p><form id="evidence-form"><label>Record type<select name="kind"><option>Before</option><option>After</option><option>Inspection</option></select></label><label>Site photo <small>Optional · PNG, JPEG or WebP · up to 4 MB</small><span class="upload-field">${icon('upload')}<b>Choose a site photo</b><span id="upload-filename">Add visual context to this record</span><input id="photo" type="file" accept="image/png,image/jpeg,image/webp"></span></label><div id="photo-preview"></div><label>Inspection / work notes <span>*</span><textarea name="note" required rows="4" maxlength="2000" placeholder="Describe the condition, work performed, checks and outcome."></textarea></label><p class="form-error" role="alert"></p><button type="submit" class="button primary full">${icon('evidence')} Save evidence record</button></form>`);let photo='';$('#photo').onchange=async event=>{const file=event.target.files[0];photo='';$('#photo-preview').innerHTML='';if(!file)return;if(file.size>4e6){toast('Choose an image smaller than 4 MB.');event.target.value='';return;}if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Use PNG, JPEG or WebP images.');event.target.value='';return;}photo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});$('#upload-filename').textContent=file.name;$('#photo-preview').innerHTML=`<img src="${photo}" alt="Selected evidence preview">`;};$('#evidence-form').onsubmit=async event=>{event.preventDefault();const button=$('button[type="submit"]',event.target);button.disabled=true;try{const body=Object.fromEntries(new FormData(event.target));body.image=photo;const updated=await api('/jobs/'+job.id+'/evidence',body);state.selected=updated;state.jobs[state.jobs.findIndex(j=>j.id===job.id)]=updated;closeDialog();render();toast('Evidence captured');}catch(error){$('.form-error',event.target).textContent=error.message;}finally{button.disabled=false;}};}
function addVariation(job) {showDialog(`<span class="dialog-eyebrow">SCOPE CONTROL / ${jobRef(job)}</span><h2>Request a scope change</h2><p>Document additional work for a separate client decision.</p><form id="variation-form"><label>Additional work / reason <span>*</span><textarea name="description" required rows="4" maxlength="2000" placeholder="Describe the added deliverable and why it is needed."></textarea></label><label>Additional scope value (AED) <span>*</span><input name="amount" type="number" required min="0.01" step="0.01" placeholder="0.00"></label><div class="security-note">${icon('file')}<p>This request will remain pending until the client approves or declines it in the handover portal.</p></div><p class="form-error" role="alert"></p><button type="submit" class="button primary full">Create change request ${icon('arrow')}</button></form>`);$('#variation-form').onsubmit=event=>submitForm(event,'/jobs/'+job.id+'/variation');}
function openEvidence(jobId, evidenceId) {const job=state.jobs.find(j=>j.id===jobId)||state.selected,record=job?.evidence.find(r=>r.id===evidenceId);if(!record)return;showDialog(`<span class="dialog-eyebrow">${jobRef(job)} / ${e(record.kind).toUpperCase()} RECORD</span><h2>Evidence detail</h2>${record.image?`<img class="evidence-full" src="${record.image}" alt="${e(record.kind)} site evidence">`:`<div class="evidence-note-banner">${icon('file')} Inspection note</div>`}<p class="record-note">${e(record.note)}</p><div class="evidence-record-meta"><span><small>WORK ORDER</small><b>${e(job.title)}</b></span><span><small>RECORDED / GST</small><b>${timestamp(record.created)}</b></span></div><button class="button secondary full" id="open-evidence-job">Open work order ${icon('arrow')}</button>`,'wide-dialog');$('#open-evidence-job').onclick=()=>{closeDialog();openJob(jobId);};}
function exportCSV() {const columns=['id','title','client','city','location','date','technician_name','status','amount'];const text=[columns.join(','),...filteredJobs().map(job=>columns.map(key=>'"'+String(job[key]??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='siteproof-work-order-register.csv';a.click();URL.revokeObjectURL(url);toast('Work order register exported');}
function printReport(job) {const w=window.open('/','_blank');if(!w)return toast('Allow pop-ups to open the handover report.');w.addEventListener('load',()=>{w.document.title=`SiteProof — ${jobRef(job)} Handover`;w.document.body.innerHTML=`<main class="print-report"><div class="print-heading"><div class="brand">${logo()}</div><span>WORK COMPLETION RECORD</span></div><p class="eyebrow">${jobRef(job)} / ${e(job.category)}</p><h1>${e(job.title)}</h1><p>${e(job.client)} · ${e(job.location)}, ${e(job.city)}</p>${badge(job.status)}<div class="print-meta"><div><small>ASSIGNED OWNER</small><b>${e(job.technician_name)}</b></div><div><small>SCHEDULED DATE</small><b>${e(job.date)}</b></div><div><small>ORIGINAL SCOPE</small><b>${currency(job.amount)}</b></div></div><h2>01 / Agreed scope</h2><p>${e(job.scope)}</p><h2>02 / Delivery checklist</h2>${job.tasks.map(t=>`<p>${t.done?'✓':'○'} ${e(t.label)}</p>`).join('')}<h2>03 / Field evidence</h2>${job.evidence.map(record=>`<section class="print-evidence">${record.image?`<img src="${record.image}" alt="${e(record.kind)} evidence">`:''}<b>${e(record.kind)}</b><p>${e(record.note)}</p><small>${timestamp(record.created)} GST</small></section>`).join('')||'<p>No evidence recorded.</p>'}<h2>04 / Scope changes</h2>${job.variations.map(v=>`<p>${e(v.description)} · ${currency(v.amount)} · ${e(v.status)}</p>`).join('')||'<p>No changes recorded.</p>'}<h2>05 / Client decisions</h2>${job.approvals.map(a=>`<section class="print-decision"><b>${e(a.name)}</b><p>${a.decision==='approve'?'Completion approved':'Issue reported'} · ${timestamp(a.created)} GST<br>${e(a.comment)}</p></section>`).join('')||'<p>No client decision recorded.</p>'}<hr><small>Generated ${new Date().toLocaleString('en-AE',{timeZone:'Asia/Dubai'})} GST. This service record is not a tax invoice, independently verified certificate or identity-verified signature.</small><div class="print-controls"><button class="button primary" id="print-now">Print / save as PDF</button></div></main>`;w.document.getElementById('print-now').onclick=()=>w.print();const images=[...w.document.images];Promise.all(images.map(img=>img.decode().catch(()=>{}))).then(()=>w.print());},{once:true});}
async function publicPortal(token) {try{const job=await api('/public/'+token),approvedExtra=job.variations.filter(v=>v.status==='Approved').reduce((s,v)=>s+v.amount,0);app.innerHTML=`<div class="client-portal"><header class="portal-header"><a class="brand" href="/">${logo()}</a><span>${icon('lock')} CLIENT HANDOVER PORTAL</span></header><main class="portal-content"><div class="portal-kicker">SERVICE DELIVERY RECORD <span>${jobRef(job)}</span></div><h1>${e(job.title)}</h1><p class="portal-site">${e(job.client)} <span>·</span> ${e(job.location)}, ${e(job.city)}</p>${badge(job.status)}<div class="portal-grid"><div><section class="panel"><div class="panel-heading"><h2>Agreed scope</h2><span class="micro-label">01 / SCOPE</span></div><div class="portal-section"><p>${e(job.scope)}</p><div class="portal-meta"><div><small>ASSIGNED OWNER</small><b>${e(job.technician_name)}</b></div><div><small>SCHEDULED VISIT</small><b>${dateLabel(job.date)}</b></div></div></div></section><section class="panel"><div class="panel-heading"><h2>Delivery checklist</h2><span class="count-badge">${job.tasks.filter(t=>t.done).length}/${job.tasks.length}</span></div><div class="portal-checklist">${job.tasks.map(task=>`<div>${icon(task.done?'check':'clock')}<span>${e(task.label)}</span><small>${task.done?'Complete':'Pending'}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-heading"><h2>Field evidence</h2><span class="count-badge">${job.evidence.length}</span></div><div class="portal-evidence">${job.evidence.map(record=>`<article>${record.image?`<img src="${record.image}" alt="${e(record.kind)} evidence">`:`<div class="portal-note-icon">${icon('file')}</div>`}<div><span class="micro-label">${e(record.kind).toUpperCase()}</span><p>${e(record.note)}</p><small>${timestamp(record.created)} GST</small></div></article>`).join('')||empty('No evidence recorded','Your service provider has not added evidence yet.')}</div></section>${job.variations.length?`<section class="panel"><div class="panel-heading"><h2>Scope change requests</h2></div><div class="portal-variations">${job.variations.map(v=>`<article><div><h3>${e(v.description)}</h3><b>${currency(v.amount)}</b>${badge(v.status)}</div>${v.status==='Pending'?`<form class="variation-decision" data-id="${v.id}"><label>Your full name<input name="name" required maxlength="200" autocomplete="name"></label><div class="share-actions"><button class="button primary" name="decision" value="Approved">Approve change</button><button class="button secondary" name="decision" value="Declined">Decline</button></div></form>`:''}</article>`).join('')}</div></section>`:''}</div><div><section class="panel portal-decision"><div class="handover-icon">${icon('approvals')}</div><span class="eyebrow">CLIENT DECISION</span><h2>Review. Confirm.<br>Close the loop.</h2><p>Review the completed work and evidence before recording your decision.</p><div class="portal-commercial"><div><span>Original scope</span><b>${currency(job.amount)}</b></div><div><span>Approved changes</span><b>${currency(approvedExtra)}</b></div><div><strong>Total agreed scope</strong><strong>${currency(job.amount+approvedExtra)}</strong></div></div>${job.status==='Awaiting approval'?`<form id="decision-form"><label>Your full name <span>*</span><input name="name" required maxlength="200" autocomplete="name"></label><label>Comments / issue details<textarea name="comment" rows="3" maxlength="2000" placeholder="Add any comments or describe an issue."></textarea></label><label class="consent"><input type="checkbox" required><span>I am authorised to record this client decision.</span></label><p class="form-error" role="alert"></p><button class="button primary full" name="decision" value="approve">${icon('check')} Approve completion</button><button class="button secondary full" name="decision" value="issue">${icon('alert')} Report an issue</button></form>`:`<div class="decision-state">${icon(job.status==='Completed'?'check':'clock')}<b>${job.status==='Completed'?'Completion recorded':'Not yet awaiting sign-off'}</b><p>${job.status==='Completed'?'The client decision is attached to this record.':'Your service provider will submit the record when it is ready.'}</p></div>`}<button class="button ghost full small" id="public-print">${icon('download')} Download handover via print</button></section>${job.approvals.map(a=>`<section class="panel decision-record ${a.decision==='issue'?'issue':''}">${icon(a.decision==='approve'?'approvals':'alert')}<h3>${a.decision==='approve'?'Client approval recorded':'Client issue recorded'}</h3><p>${e(a.comment||'No comment provided.')}</p><b>${e(a.name)}</b><small>${timestamp(a.created)} GST</small></section>`).join('')}</div></div><div class="portal-disclaimer">${icon('lock')} This link provides access to one work order. Client names are self-declared and decisions are recorded with timestamps.</div></main><footer class="portal-footer"><span>SiteProof UAE</span><span>Evidence-led service delivery.</span></footer></div>`;$('#public-print').onclick=()=>printReport(job);$('#decision-form')?.addEventListener('submit',event=>submitDecision(event,'decision',token));$$('.variation-decision').forEach(form=>form.onsubmit=event=>submitDecision(event,'variation',token));}catch(error){app.innerHTML=`<main class="portal-error"><div class="brand">${logo()}</div>${icon('lock')}<h1>This handover is unavailable.</h1><p>${e(error.message)}</p><a class="button secondary" href="/">Return to workspace ${icon('arrow')}</a></main>`;}}
async function submitDecision(event, type, token) {event.preventDefault();const body=Object.fromEntries(new FormData(event.target));if(type==='decision')body.decision=event.submitter.value;else{body.status=event.submitter.value;body.id=+event.target.dataset.id;}const buttons=$$('button',event.target);buttons.forEach(b=>b.disabled=true);try{await api('/public/'+token+'/'+type,body);toast('Your decision has been recorded');await publicPortal(token);}catch(error){const target=$('.form-error',event.target);if(target)target.textContent=error.message;else toast(error.message);buttons.forEach(b=>b.disabled=false);}}
if(location.pathname.startsWith('/approve/')||location.hash.startsWith('#/approve/'))publicPortal(location.pathname.startsWith('/approve/')?location.pathname.split('/')[2]:location.hash.split('/')[2]);else load().catch(error=>{if(error.message==='Please sign in')login();else{app.innerHTML=`<main class="portal-error"><h1>Workspace unavailable</h1><p>${e(error.message)}</p><button class="button primary" id="retry">Retry connection</button></main>`;$('#retry').onclick=()=>location.reload();}});
